#include <stdio.h>
#include <stdlib.h>
#include <string.h>

FILE *open_file(const char *path, const char *mode) {
    FILE *file = fopen(path, mode);
    if (!file) { perror(path); exit(1); }
    return file;
}
void show_file(const char *path) {
    FILE *file = open_file(path, "r");
    int ch;
    while ((ch = fgetc(file)) != EOF) putchar(ch);
    fclose(file);
}
void copy_file(const char *source, const char *target) {
    FILE *in = open_file(source, "rb"), *out = open_file(target, "wb");
    int ch;
    while ((ch = fgetc(in)) != EOF) fputc(ch, out);
    fclose(in); fclose(out);
}

int main(void) {
    int n;
    char words[100][101];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%100s", words[i]);
    for (int i = 0; i < n - 1; i++) for (int j = i + 1; j < n; j++)
        if (strcmp(words[i], words[j]) > 0) {
            char temporary[101]; strcpy(temporary, words[i]); strcpy(words[i], words[j]); strcpy(words[j], temporary);
        }
    FILE *file = open_file("words.txt", "w");
    for (int i = 0; i < n; i++) fprintf(file, "%s\n", words[i]);
    fclose(file);
    show_file("words.txt");
    return 0;
}
